	// Candidate 1: PackedPlanCache.sameSource accepts TupleExpr.equals, which ignores ArbitraryLengthPath.minLength.
	@Test
	void packedPlanCacheMustNotServeStarPathPlanForPlusPath(@TempDir File dataDir, @TempDir File oracleDir) {
		String star = "SELECT ?s ?o WHERE { ?s <urn:p>* ?o }";
		String plus = "SELECT ?s ?o WHERE { ?s <urn:p>+ ?o }";
		Set<String> oracle = oracle(oracleDir, connection -> connection.add(A, P, B), plus, "s", "o");

		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			TupleExpr starPlan = explain(connection, star);
			report("star-plan", starPlan);
			Set<String> plusRows = rows(connection, plus, "s", "o");
			TupleExpr plusPlan = explain(connection, plus);
			report("plus-plan", plusPlan);

			assertEquals(Set.of("urn:a|urn:b"), oracle, "cold oracle");
			assertEquals(oracle, plusRows, "p+ must not return zero-length rows from a cached p* plan");
		} finally {
			repository.shutDown();
		}
	}

	// Candidate 2 end-to-end (best effort race): concurrent cold planning of two constants of one parameterized
	// family; the out-of-domain constant proves EmptySet, the in-domain one must still return its row.
	@Test
	void concurrentFamilyPlanningMustNotShareEmptyProof(@TempDir File dataDir) throws Exception {
		SailRepository repository = repository(dataDir);
		java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);
		try (RepositoryConnection loader = repository.getConnection()) {
			loader.add(A, P, VF.createLiteral("7", XSD.INTEGER));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();
			int wrong = 0;
			int iterations = 300;
			for (int i = 0; i < iterations; i++) {
				String variable = "s" + i;
				String inDomain = "SELECT ?" + variable + " WHERE { ?" + variable + " <urn:p> 7 }";
				String outOfDomain = "SELECT ?" + variable + " WHERE { ?" + variable + " <urn:p> 9 }";
				java.util.concurrent.CyclicBarrier barrier = new java.util.concurrent.CyclicBarrier(2);
				java.util.concurrent.Future<Set<String>> empty = executor.submit(() -> {
					try (RepositoryConnection connection = repository.getConnection()) {
						barrier.await();
						return rows(connection, outOfDomain, variable);
					}
				});
				java.util.concurrent.Future<Set<String>> present = executor.submit(() -> {
					try (RepositoryConnection connection = repository.getConnection()) {
						barrier.await();
						return rows(connection, inDomain, variable);
					}
				});
				empty.get();
				if (!Set.of("urn:a").equals(present.get())) {
					wrong++;
				}
			}
			System.out.println("=== REVIEW-REPRO concurrent family wrong=" + wrong + "/" + iterations);
			assertEquals(0, wrong, "in-domain constant lost its row in " + wrong + " of " + iterations + " races");
		} finally {
			executor.shutdownNow();
			repository.shutDown();
		}
	}

	// Candidate 1 (second instance): GroupConcat.equals ignores the separator.
	@Test
	void packedPlanCacheMustNotServeGroupConcatPlanWithOtherSeparator(@TempDir File dataDir) {
		String comma = "SELECT (GROUP_CONCAT(STR(?o); separator=\",\") AS ?c) WHERE { ?s <urn:p> ?o }";
		String pipe = "SELECT (GROUP_CONCAT(STR(?o); separator=\"|\") AS ?c) WHERE { ?s <urn:p> ?o }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("x"));
			connection.add(B, P, VF.createLiteral("y"));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			report("comma-plan", explain(connection, comma));
			Set<String> pipeRows = rows(connection, pipe, "c");
			report("pipe-plan", explain(connection, pipe));

			assertEquals(1, pipeRows.size());
			String value = pipeRows.iterator().next();
			assertEquals(true, value.contains("|") && !value.contains(","),
					"GROUP_CONCAT with separator '|' returned '" + value + "'");
		} finally {
			repository.shutDown();
		}
	}

	// Candidate 5: pipeline decision cache serves (USE_AND_REFRESH) a plan whose exact stored-term VALUES anchor was
	// enumerated before a later commit added another value-equal term.
	@Test
	void exactStoredTermAnchorMustNotSurviveCommitThatAddsValueEqualTerm(@TempDir File dataDir,
			@TempDir File oracleDir) {
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 5) }";
		Set<String> oracle = oracle(oracleDir, connection -> {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			connection.add(C, P, VF.createLiteral("5", XSD.INT));
		}, query, "s");

		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertEquals(Set.of("urn:a"), rows(connection, query, "s"));
			report("before-commit", explain(connection, query));

			connection.add(C, P, VF.createLiteral("5", XSD.INT));

			Set<String> afterCommit = rows(connection, query, "s");
			report("after-commit", explain(connection, query));

			assertEquals(Set.of("urn:a", "urn:c"), oracle, "cold oracle");
			assertEquals(oracle, afterCommit, "a committed value-equal term must be visible to the re-run query");
		} finally {
			repository.shutDown();
		}
	}

